"""Standalone scientific HTML from saved WM artifacts; no model/GPU imports."""
import json,html
from pathlib import Path
from datetime import datetime,timezone
HERE=Path(__file__).resolve().parent


def render():
    r=json.loads((HERE/'results.json').read_text())
    r['rendered_utc']=datetime.now(timezone.utc).isoformat()
    payload=json.dumps(r).replace('</','<\\/')
    document=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Trace memory under stress · Visual Working Memory</title>
<style>
:root{--paper:#f5f2eb;--ink:#152b2a;--muted:#637773;--line:#d3ddd4;--teal:#056f65;--lime:#d3ec8c;--orange:#b45331}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:system-ui,Segoe UI,sans-serif;line-height:1.5}main{max-width:1260px;margin:auto;padding:42px 38px 80px}nav{display:flex;gap:24px;align-items:center;border-bottom:1px solid var(--line);padding-bottom:20px;font-size:12px;letter-spacing:.12em;text-transform:uppercase}nav b{margin-right:auto}a{color:var(--teal)}nav a{color:inherit;text-decoration:none}header{padding:72px 0 46px;display:grid;grid-template-columns:1.25fr 1fr;gap:70px}h1{font:500 clamp(45px,6vw,79px)/1.03 Georgia,serif;letter-spacing:-.035em;margin:16px 0 25px}h2{font:500 36px/1.1 Georgia,serif;margin:0 0 20px}h3{font-size:17px;margin:0 0 10px}.kicker{font-size:11px;text-transform:uppercase;letter-spacing:.16em;font-weight:700}.lead{font-size:19px;color:var(--muted);max-width:640px}.pill{display:inline-block;padding:5px 12px;background:var(--lime);border-radius:99px;font-size:12px;letter-spacing:.06em}.summary{align-self:end;border-top:3px solid var(--ink);padding-top:18px}.summary p{font-size:15px}.stats{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--line);margin:12px 0 50px}.stat{padding:22px;border-right:1px solid var(--line)}.stat:last-child{border:0}.stat strong{font:500 31px Georgia,serif;display:block}.stat small{font-size:11px;text-transform:uppercase;letter-spacing:.1em;color:var(--muted)}section{padding:42px 0;border-top:1px solid var(--line)}.intro{display:flex;justify-content:space-between;gap:40px;align-items:end;margin-bottom:24px}.intro p{max-width:650px;color:var(--muted);margin:0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.card{padding:24px;background:#fffdf8;border:1px solid var(--line);border-radius:12px}.card p{font-size:14px;color:var(--muted)}.diagram{background:var(--ink);border-radius:16px;color:#e3f0e6;padding:30px;margin:22px 0}.flow{display:grid;grid-template-columns:1fr 35px 1fr 35px 1.4fr 35px 1fr;align-items:center;text-align:center;gap:8px}.flow div{padding:16px 8px;border:1px solid #52736a;border-radius:9px;font-size:13px}.flow span{color:var(--lime);font-size:24px}.flow small{display:block;color:#9db9b0;font-size:10px;margin-top:6px}.eq{margin:14px auto;text-align:center;font-size:21px}math{font-family:Cambria Math,STIX Two Math,serif}select,button{font:inherit;border:1px solid var(--line);border-radius:8px;background:#fffdf8;color:var(--ink);padding:9px 14px;cursor:pointer}button.active{background:var(--ink);color:white;border-color:var(--ink)}.controls{display:flex;flex-wrap:wrap;gap:8px;margin:20px 0}.small{font-size:12px;color:var(--muted)}.tablewrap{overflow:auto;background:#fffdf8;border:1px solid var(--line);border-radius:12px}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums;font-size:13px}th,td{padding:14px 12px;border-bottom:1px solid var(--line);text-align:center;white-space:nowrap}th{font-size:11px;color:var(--muted);font-weight:600}th:first-child,td:first-child{text-align:left;position:sticky;left:0;background:#fffdf8;z-index:1}td button{border:0;min-width:70px;padding:12px 6px;font-weight:650}.empty{background:#e8ece6!important;color:#8b9890!important}.legend{display:flex;gap:16px;align-items:center;margin:14px 0;font-size:11px;color:var(--muted)}.gradient{width:150px;height:8px;background:linear-gradient(to right,#ecf0e8,#056f65);border-radius:20px}.detail{margin-top:22px;padding:22px;background:white;border-left:4px solid var(--teal);display:none}.detail.open{display:block}.detail pre{font-size:12px;white-space:pre-wrap;color:var(--muted)}.timeline{height:215px;width:100%;background:#fffdf8;border:1px solid var(--line);border-radius:12px}.footnote{padding:18px 22px;border-left:2px solid var(--orange);background:#eee9dd;font-size:13px;margin:25px 0}.muted{color:var(--muted)}footer{padding-top:35px;font-size:12px;color:var(--muted)}.narrative{max-width:900px}code{font-size:12px;word-break:break-all}details{padding:15px 0;border-bottom:1px solid var(--line)}summary{cursor:pointer;font-weight:600}svg text{font-family:system-ui;font-size:11px;fill:var(--muted)}@media(max-width:850px){main{padding:22px 18px}header{grid-template-columns:1fr;gap:24px;padding:40px 0}.stats{grid-template-columns:1fr 1fr}.stat:nth-child(2){border:0}.grid{grid-template-columns:1fr}.intro{display:block}.flow{grid-template-columns:1fr}.flow span{transform:rotate(90deg)}nav{gap:12px;flex-wrap:wrap}h2{font-size:30px}}
</style><main><nav><b>Visual attention & working memory</b><a href="#model">Computation</a><a href="#results">Evidence</a><a href="#learning">Learning</a><a href="#scope">Interpretation</a></nav>
<header><div><span class="kicker">Experiment / opponent sequence learner</span><h1>Trace memory<br>under stress.</h1><p class="lead">Training a visual system to integrate, retain and retrieve information across a stream. Where does its existing temporal state suffice?</p></div><div class="summary"><span class="pill" id="status"></span><p id="headline"></p><p id="outcome"></p><p class="small">One pretrained opponent model. All learned weights adapt. Fixed temporal retentions and quadrature filters remain unchanged.</p></div></header>
<div class="stats" id="stats"></div>
<section id="model"><div class="intro"><h2>The computation stays explicit.</h2><p>Each image is processed once in temporal order. Only two spatial traces per encoder scale carry history; the readout receives current features and the emitted trace representation.</p></div>
<div class="diagram"><div class="flow"><div>Current RGB frame<small>100 ×100 ×3</small></div><span>→</span><div>Learned encoder + projections<small>All learned weights unfrozen</small></div><span>→</span><div>Fast + slow traces<small>Three spatial scales · fixed retention</small></div><span>→</span><div>Opponent energy + readout<small>One response at the report</small></div></div>
<div class="eq"><math display="block"><msub><mi>F</mi><mi>t</mi></msub><mo>=</mo><mn>0.25</mn><msub><mi>F</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub><mo>+</mo><mn>0.75</mn><msub><mi>U</mi><mi>t</mi></msub><mspace width="2em"/><msub><mi>L</mi><mi>t</mi></msub><mo>=</mo><mn>0.75</mn><msub><mi>L</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub><mo>+</mo><mn>0.25</mn><msub><mi>U</mi><mi>t</mi></msub></math></div>
<p class="small" style="color:#b6cdc3">At reset, both traces initialize from the first actual frame. Energy and readout outputs do not feed back into the trace update. Full episode gradients pass through the encoder; exact activation checkpointing reduces training memory without truncation.</p></div>
<div class="grid"><article class="card"><span class="kicker">01 / integrate</span><h3>Combine relevant evidence</h3><p>Motion asks which direction occupied the most total transitions, including revisits. Scalar tasks accumulate changes in the visually cued sign.</p><div class="eq"><math><msub><mi>A</mi><mi>c</mi></msub><mo>=</mo><munder><mo>∑</mo><mi>t</mi></munder><mi>max</mi><mo>(</mo><mn>0</mn><mo>,</mo><mi>c</mi><mi>Δ</mi><msub><mi>x</mi><mi>t</mi></msub><mo>)</mo></math></div></article><article class="card"><span class="kicker">02 / retain</span><h3>Keep a decision available</h3><p>The evidence ends before blank or irrelevant images. Reporting later tests decision retention, which can preserve a category rather than the original visual stream.</p></article><article class="card"><span class="kicker">03 / retrieve</span><h3>Use an item after its identity is queried</h3><p>Identity-tagged samples precede the query. Binary match/change depends on the new probe, so the answer cannot be computed before the retention interval. Motion uses categorical recall.</p></article></div></section>
<section id="results"><div class="intro"><h2>Every capability gets its own view.</h2><p>Balanced accuracy is shown by family and condition. Cell colors use improvement above that task's chance level—25% for motion,50% for binary tasks.</p></div>
<div class="controls" id="sources"></div><div class="controls" id="tabs"></div><div id="heatmap" class="tablewrap"></div><div class="legend"><span>Chance</span><span class="gradient"></span><span>Perfect empirical score</span><span>— = not yet evaluated</span></div><div id="cell-detail" class="detail"></div><p class="small" id="metric-note"></p></section>
<section id="learning"><div class="intro"><h2>Acquisition before interpretation.</h2><p>A short bridge teaches the new formats. Its weights and fresh Adam state continue into the joint mixture; no accuracy gate stops healthy training.</p></div><svg class="timeline" id="curve" viewBox="0 0 1100 215" role="img" aria-label="Validation AUC learning trajectory"></svg><div class="tablewrap" style="margin-top:20px" id="curve-table"></div><p class="small">Joint selection averages conditions within each family/protocol group and then gives those groups equal weight. Bridge validation is a distinct stage. Final tests never select checkpoints.</p></section>
<section id="scope"><div class="intro"><h2>A capacity profile, not a forced verdict.</h2><p>Short sensory/cue learning, long-sequence inference and out-of-distribution generalization are distinct outcomes.</p></div><div class="narrative"><p>Two histories followed by identical later images have trace differences that decay geometrically:</p><div class="eq"><math display="block"><mi>Δ</mi><msub><mi>F</mi><mi>D</mi></msub><mo>=</mo><msup><mn>0.25</mn><mi>D</mi></msup><mi>Δ</mi><msub><mi>F</mi><mn>0</mn></msub><mspace width="2em"/><mi>Δ</mi><msub><mi>L</mi><mi>D</mi></msub><mo>=</mo><msup><mn>0.75</mn><mi>D</mi></msup><mi>Δ</mi><msub><mi>L</mi><mn>0</mn></msub></math></div><p>This is a structural equation, not an accuracy theorem. Small residuals, readout amplification and finite precision matter. The encoder may use a cue visible in its current image, while remembered cues cannot feed back into that stateless encoder.</p><div class="footnote">If the new minimal-delay rules remain poorly acquired, stronger memory-limit claims are inconclusive. A finite training allowance is not a sufficient acquisition horizon. Any proposed memory addition must address an observed deficit and compete with improving the current computation.</div><details><summary>Exposure and uncertainty</summary><p>One fresh history/query/answer is one episode. Cues, repeated images, blanks and probes count as encoder updates, not independent episodes. Natural-image intervals cluster by the queried target photo; uncued-photo reuse is not separately clustered. Estimates concern this fitted model and source pool, not variation across training seeds. Empirical perfect-score intervals can collapse without proving population certainty.</p></details><details><summary>What this allocation includes</summary><p>Trained-condition slices cover integration length, visible/flashed cues, blank retention, interference, item load and timing controls. The fixed run excludes optional64-transition, delay32 and load6 extrapolation. A generator counterfactual construction is verified, but no extra model sweep is silently added.</p></details><details><summary>Reproducible evidence</summary><p id="identity"></p><p><a href="results.json">Machine-readable results</a> · <a href="report.md">Full scientific report</a> · <a href="TASK_BATTERY.md">Task specification</a> · <a href="Research/sequence_generator_notes.md">Generator constraints</a></p></details></div></section><footer id="footer"></footer>
<script id="data" type="application/json">PAYLOAD</script><script>
const R=JSON.parse(document.getElementById('data').textContent),C=R.config, Q=C.recipe||{}, families=Object.keys(C.task_classes||{}), pretty={motion_direction:'Motion direction',orientation:'Orientation',contrast:'Contrast',spatial_frequency:'Spatial frequency',chromatic_increment:'Chromatic increment',contour:'Contour',natural_spectrum:'Natural detail'};
const $=id=>document.getElementById(id), pct=x=>(x*100).toFixed(1)+'%', num=x=>Number(x||0).toLocaleString(), esc=s=>String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const groups={Bridge:['anchor','bridge_integrate_visible','bridge_integrate_transient','bridge_recall'],Integration:['integrate_L8','integrate_L16','integrate_L32','integrate_transient'],Retention:['integrate_L8','decision_D2','decision_D4','decision_D8','decision_D16','decision_distractor'],Recall:['recall_D0','recall_D2','recall_N1','recall_D8','recall_D16'],Load:['recall_N1','recall_N2','recall_N4','recall_matched_one','recall_distractor','recall_precue','recall_postcue']};
let selectedGroup='Bridge',selectedSource='Final held-out test';const sources={'Final held-out test':R.test};for(const v of R.validation||[])sources[`Validation · ${v.stage} · ${num(v.step*Q.batch_size)} episodes`]=v;
$('status').textContent=R.status.replaceAll('_',' ');$('headline').textContent=R.status==='completed'?`Completed ${num(C.total_episodes)} training episodes. Selected update ${num(R.selected_step)}; all declared held-out cells are now available.`:`The fixed run targets ${num(C.total_episodes)} complete episodes. Final held-out evidence remains pending until its saved evaluation finishes.`;
if(R.status==='completed'){const mean=p=>{let a=Object.values(R.test.cells).filter(c=>c.protocol===p).map(c=>c.overall.macro_ovr_auc);return(a.reduce((s,x)=>s+x,0)/a.length).toFixed(3)};$('outcome').textContent=`Held-out mean AUC: sensory ${mean('anchor')}, integration ${mean('integration')}, recall ${mean('recall')}. The new minimal-delay rules remain weak, so harder-condition deficits do not cleanly isolate memory capacity. Some chance-level decisions retain useful score ranking.`;}
const stats=[['Training episodes',num(C.total_episodes)],['Learned parameters','408,728'],['Maximum allowance','4 hours'],['Selected update',R.selected_step?num(R.selected_step):'Pending']];$('stats').innerHTML=stats.map(([l,v])=>`<div class="stat"><strong>${v}</strong><small>${l}</small></div>`).join('');
function controls(){ $('sources').innerHTML=Object.keys(sources).map(x=>`<button class="${x===selectedSource?'active':''}" data-source="${esc(x)}">${esc(x)}</button>`).join('');$('tabs').innerHTML=Object.keys(groups).map(x=>`<button class="${x===selectedGroup?'active':''}" data-group="${x}">${x}</button>`).join('');document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{selectedSource=b.dataset.source;draw()});document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{selectedGroup=b.dataset.group;draw()});}
function draw(){controls();let d=sources[selectedSource],conditions=groups[selectedGroup];$('heatmap').innerHTML='<table><thead><tr><th>Family</th>'+conditions.map(x=>`<th>${x.replaceAll('_','<br>')}</th>`).join('')+'</tr></thead><tbody>'+families.map(f=>'<tr><td>'+pretty[f]+'</td>'+conditions.map(c=>{let cell=d?.cells?.[f+'/'+c]?.overall;if(!cell)return '<td><button class="empty" disabled>—</button></td>';let score=Math.max(0,Math.min(1,(cell.balanced_accuracy-cell.chance_accuracy)/(1-cell.chance_accuracy))),bg=`hsl(${160+score*10} ${15+score*78}% ${94-score*70}%)`;return `<td><button data-cell="${f+'/'+c}" style="background:${bg};color:${score>.55?'white':'#243b35'}">${pct(cell.balanced_accuracy)}</button></td>`}).join('')+'</tr>').join('')+'</tbody></table>';$('metric-note').textContent=selectedSource==='Final held-out test'?(R.test?'128 episodes per cell · fixed argmax ·500-replicate intervals in cell details.':'Final test pending. Validation views are explicitly separate.'):'Validation data only; this view is not held-out confirmation.';$('cell-detail').classList.remove('open');document.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>{let c=d.cells[b.dataset.cell],v=c.overall,fmt=a=>a?a.map(x=>pct(x)).join(' – '):'not estimated';$('cell-detail').innerHTML=`<h3>${pretty[c.family]} / ${c.condition}</h3><p>BA <b>${pct(v.balanced_accuracy)}</b> (${fmt(v.balanced_accuracy_ci95)}); OVR-AUC <b>${v.macro_ovr_auc.toFixed(4)}</b>. n=${v.n}; source groups=${v.unique_base_groups}.</p><p class="small">Confusion matrix: true classes in rows, predictions in columns.</p><pre>${esc(JSON.stringify(v.confusion_true_rows_pred_columns))}</pre><details><summary>Full metrics and strata</summary><pre>${esc(JSON.stringify(c,null,2))}</pre></details>`;$('cell-detail').classList.add('open')});}
draw();let vs=R.validation||[],max=C.total_episodes||1,X=x=>65+x/max*980,Y=y=>175-y*140;let svg='';for(let y of [.25,.5,.75,1])svg+=`<line x1="65" y1="${Y(y)}" x2="1045" y2="${Y(y)}" stroke="#d3ddd4"/><text x="20" y="${Y(y)+4}">${y.toFixed(2)}</text>`;let joint=vs.filter(v=>v.stage==='joint');if(joint.length)svg+=`<polyline points="${joint.map(v=>`${X(v.step*Q.batch_size)},${Y(v.selection_mean_auc)}`).join(' ')}" fill="none" stroke="#056f65" stroke-width="3"/>`;for(let v of vs)svg+=`<circle cx="${X(v.step*Q.batch_size)}" cy="${Y(v.selection_mean_auc)}" r="5" fill="${v.stage==='bridge'?'#b45331':'#056f65'}"/><text x="${X(v.step*Q.batch_size)}" y="198" text-anchor="middle">${num(v.step*Q.batch_size)}</text>`;svg+='<text x="18" y="18">AUC</text><text x="1000" y="18">Episodes</text>';$('curve').innerHTML=svg;$('curve-table').innerHTML='<table><tr><th>Stage</th><th>Episodes</th><th>Mean AUC</th><th>Worst cell BA</th></tr>'+vs.map(v=>`<tr><td>${v.stage}</td><td>${num(v.step*Q.batch_size)}</td><td>${v.selection_mean_auc.toFixed(4)}</td><td>${pct(v.worst_cell_ba)}</td></tr>`).join('')+'</table>';
$('identity').innerHTML=`Parent checkpoint: <code>${esc(C.parent_checkpoint||'')}</code><br>Run: <code>${esc(R.run_root)}</code><br>Bridge ${num(C.bridge_episodes)} episodes; joint ${num(C.joint_episodes)}. Batch ${Q.batch_size||'pending'}, fp32, fresh Adam, full sequence gradients.`;$('footer').textContent=`Saved-data snapshot ${R.rendered_utc}. Status: ${R.status}. `+(R.wall_seconds?`Supervisor wall time ${(R.wall_seconds/60).toFixed(2)} minutes.`:'Training/evaluation is not yet complete.');
</script></main></html>'''.replace('PAYLOAD',payload)
    path=HERE/'report.html';path.write_text(document,encoding='utf-8');print(path)

if __name__=='__main__':render()
